// Sandboxed workspace file ops (write/read/list/delete) -- no server needed.
// Requires NODE_FUNCTION_ALLOW_BUILTIN=fs,path on the n8n process.
const fsMod = require('fs');
const pathMod = require('path');
const WS_ROOT = '@@PROJECT_ROOT@@\\workspace';
const READ_CAP = 15000;

const j = $input.first().json;
const op = String(j.operation || 'list').toLowerCase();
const session = String(j.session || '').replace(/[^a-zA-Z0-9]/g, '').slice(0, 8);
const fail = (error) => [{ json: { result: JSON.stringify({ ok: false, error }) } }];
if (!session) return fail('missing or invalid session');
// The session's working folder: chosen on the APEX Squad web page (workspace/.squad-sessions/<session>.json),
// else "workingFolder" in squad-install.config.json, else WS_ROOT. Same rule as the Squad Code nodes.
function workingFolder(key) {
  const read = (f) => { try { return JSON.parse(fsMod.readFileSync(f, 'utf8')) || {}; } catch (e) { return {}; } };
  return read(pathMod.join(WS_ROOT, '.squad-sessions', key + '.json')).workingFolder ||
    read(pathMod.join(WS_ROOT, '..', 'squad-install.config.json')).workingFolder || WS_ROOT;
}
const dir = pathMod.join(workingFolder(session), session);

function safeJoin(rel) {
  const clean = String(rel || '').replace(/\\/g, '/').replace(/^[A-Za-z]:/, '')
    .split('/').filter((s) => s && s !== '.' && s !== '..').join(pathMod.sep);
  if (!clean) return null;
  const abs = pathMod.join(dir, clean);
  if (!abs.startsWith(dir + pathMod.sep) && abs !== dir) return null;
  return { abs, rel: clean.replace(/\\/g, '/') };
}

function listFiles(d) {
  const out = [];
  if (!fsMod.existsSync(d)) return out;
  for (const e of fsMod.readdirSync(d, { withFileTypes: true })) {
    const full = pathMod.join(d, e.name);
    if (e.isDirectory()) out.push(...listFiles(full));
    else out.push({ path: pathMod.relative(dir, full).split(pathMod.sep).join('/'), bytes: fsMod.statSync(full).size });
  }
  return out;
}

if (op === 'list') {
  return [{ json: { result: JSON.stringify({ ok: true, workspace: 'workspace/' + session, files: listFiles(dir) }) } }];
}
const target = safeJoin(j.file_path);
if (!target) return fail('missing or invalid file_path (relative paths only, e.g. src/app.js)');
if (op === 'write') {
  const content = j.content;
  if (typeof content !== 'string' || content.length === 0) return fail('content (non-empty string) is required -- pass the COMPLETE file content');
  fsMod.mkdirSync(pathMod.dirname(target.abs), { recursive: true });
  fsMod.writeFileSync(target.abs, content, 'utf8');
  return [{ json: { result: JSON.stringify({ ok: true, wrote: target.rel, bytes: Buffer.byteLength(content, 'utf8') }) } }];
}
// spec.md (the technical requirement) is always returned whole: every agent must see all of it,
// the acceptance checks at the end included. Other files come in parts of READ_CAP chars from offset.
if (op === 'read') {
  if (!fsMod.existsSync(target.abs)) return fail('file not found: ' + target.rel + ' -- use FS_List to see what exists');
  const text = fsMod.readFileSync(target.abs, 'utf8');
  const whole = pathMod.basename(target.rel).toLowerCase() === 'spec.md';
  const offset = whole ? 0 : Math.max(0, parseInt(j.offset, 10) || 0);
  if (offset && offset >= text.length) return fail('offset ' + offset + ' is past the end of ' + target.rel + ' (' + text.length + ' chars)');
  const content = whole ? text : text.slice(offset, offset + READ_CAP);
  const end = offset + content.length;
  const res = { ok: true, file: target.rel, size: text.length, offset, truncated: end < text.length, content };
  if (res.truncated) res.next = 'call FS_Read again with offset ' + end + ' for the rest (' + (text.length - end) + ' more chars)';
  return [{ json: { result: JSON.stringify(res) } }];
}
if (op === 'delete') {
  // .apexlang/ is the shared state and history, maintained by the Squad Code nodes.
  if (target.rel === '.apexlang' || target.rel.startsWith('.apexlang/')) return fail('files under .apexlang/ are maintained by code and cannot be deleted');
  if (!fsMod.existsSync(target.abs)) return fail('file not found: ' + target.rel + ' -- use FS_List to see what exists');
  if (!fsMod.statSync(target.abs).isFile()) return fail('only single files can be deleted, not folders: ' + target.rel);
  fsMod.unlinkSync(target.abs);
  return [{ json: { result: JSON.stringify({ ok: true, deleted: target.rel }) } }];
}
return fail('unknown operation: ' + op);
